88	bool PhysicsDebugDraw::init(DrawNode* drawNode)
89	{
90	    if (drawNode == nullptr)
91	    {
92	        return false;
93	    }
94	
95	    // the draw node is owned by the caller, it is only borrowed here
96	    _drawNode = drawNode;
97	    _drawNode->setLineWidth(_config.lineWidth);
98	    _drawNode->setLocalZOrder(kDebugDrawLocalZOrder);
99	    _initialized = true;
100	
101	    return true;
102	}
103	
104	void PhysicsDebugDraw::setConfig(const PhysicsDebugDrawConfig& config)
105	{
106	    _config = config;
107	
108	    if (_drawNode != nullptr)
109	    {
110	        _drawNode->setLineWidth(_config.lineWidth);
111	    }
112	}
