357	void PhysicsDebugDraw::drawJoint(PhysicsJoint* joint)
358	{
359	    if (_drawNode == nullptr || joint == nullptr)
360	    {
361	        return;
362	    }
363	
364	    PhysicsBody* bodyA = joint->getBodyA();
365	    PhysicsBody* bodyB = joint->getBodyB();
366	    if (bodyA == nullptr || bodyB == nullptr)
367	    {
368	        return;
369	    }
370	
371	    const Color4F& color = _config.jointColor;
372	
373	    auto spring = dynamic_cast<PhysicsJointSpring*>(joint);
374	    if (spring != nullptr)
375	    {
376	        drawSpringJoint(bodyA->local2World(spring->getAnchr1()),
377	                        bodyB->local2World(spring->getAnchr2()),
378	                        spring->getRestLength(), color);
379	        return;
380	    }
381	
382	    auto limit = dynamic_cast<PhysicsJointLimit*>(joint);
383	    if (limit != nullptr)
384	    {
385	        drawSlideJoint(bodyA->local2World(limit->getAnchr1()),
386	                       bodyB->local2World(limit->getAnchr2()),
387	                       limit->getMin(), limit->getMax(), color);
388	        return;
389	    }
390	
391	    auto groove = dynamic_cast<PhysicsJointGroove*>(joint);
392	    if (groove != nullptr)
393	    {
394	        const Vec2 grooveA = bodyA->local2World(groove->getGrooveA());
395	        const Vec2 grooveB = bodyA->local2World(groove->getGrooveB());
396	        const Vec2 anchr2 = bodyB->local2World(groove->getAnchr2());
397	
398	        drawSlideJoint(grooveA, grooveB, 0.0f, grooveA.distance(grooveB), color);
399	        drawPinJoint(anchr2, grooveA, color);
400	        return;
401	    }
402	
403	    // fixed, distance, pin and the rotary joints all pivot around the body origins
404	    drawPinJoint(bodyA->local2World(Vec2::ZERO), bodyB->local2World(Vec2::ZERO), color);
405	}
