407	void PhysicsDebugDraw::drawCircleShape(const Vec2& center, float radius, float angle,
408	                                       const Color4F& fillColor, const Color4F& outlineColor)
409	{
410	    if (_drawNode == nullptr || radius <= 0.0f)
411	    {
412	        return;
413	    }
414	
415	    Vec2 seg[kCircleSegments];
416	    for (int i = 0; i < kCircleSegments; ++i)
417	    {
418	        const float theta = angle + static_cast<float>(i) * kPi * 2.0f / static_cast<float>(kCircleSegments);
419	        seg[i] = center + Vec2(radius * std::cos(theta), radius * std::sin(theta));
420	    }
421	
422	    _drawNode->drawPolygon(seg, kCircleSegments, fillColor, _config.lineWidth, outlineColor);
423	    // the spoke makes the rotation of the body visible
424	    _drawNode->drawLine(center, seg[0], outlineColor);
425	    _drawNode->drawDot(center, kCircleCenterDotRadius, outlineColor);
426	}
427	
428	void PhysicsDebugDraw::drawPolygonShape(const Vec2* verts, int count,
429	                                        const Color4F& fillColor, const Color4F& outlineColor)
430	{
431	    if (_drawNode == nullptr || verts == nullptr || count < 2)
432	    {
433	        return;
434	    }
435	
436	    if (count == 2)
437	    {
438	        drawSegmentShape(verts[0], verts[1], _config.lineWidth, outlineColor);
439	        return;
440	    }
441	
442	    _drawNode->drawPolygon(verts, count, fillColor, _config.lineWidth, outlineColor);
443	}
