609	    _drawNode->drawLine(anchorA, anchorB, color);
610	    _drawNode->drawDot(anchorA, kJointAnchorRadius, color);
611	    _drawNode->drawDot(anchorB, kJointAnchorRadius, color);
612	
613	    const Vec2 delta = anchorB - anchorA;
614	    const float length = delta.getLength();
